function [q] = fromrotvec(th)
%FROMROTVEC  The quaternion of a rotation vector: [sin(|t|/2) t/|t|, cos(|t|/2)]; below 1e-12 rad
%   [t/2, 1] made unit.
%   th: real[1][3] (passed a plain number)
%   returns q: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    q = zeros(4, 1);
    a = asils.pc.norm_(th);
    if (a < 1e-12)
        q = asils.groups.shared.qnorm([(th(1) / 2); (th(2) / 2); (th(3) / 2); 1]);
    else
        q = [((sin((a / 2)) * th(1)) / a); ((sin((a / 2)) * th(2)) / a); ((sin((a / 2)) * th(3)) / a); cos((a / 2))];
    end
end
